import json
from pathlib import Path

from sqlalchemy.orm import Session

from nasd.models import AclEntry, Share, Volume
from nasd.settings import settings


def render_samba(db: Session) -> str:
    shares = db.query(Share).all()
    lines = [
        "# Generated by nasd — do not edit manually",
        "[global]",
        "   workgroup = WORKGROUP",
        "   server string = OpenNAS-Lite",
        "   security = user",
        "   map to guest = Bad User",
        "   vfs objects = catia fruit streams_xattr",
        "   fruit:metadata = stream",
        "",
    ]
    for share in shares:
        vol = db.get(Volume, share.volume_id)
        if vol is None:
            continue
        path = vol.mount_path
        opts = json.loads(share.smb_options_json or "{}")
        browseable = "yes" if opts.get("browseable", True) else "no"
        time_machine = opts.get("time_machine", False)
        lines.extend(
            [
                f"[{share.name}]",
                f"   path = {path}",
                "   browseable = " + browseable,
                "   read only = no",
                "   guest ok = no",
            ]
        )
        if time_machine:
            lines.append("   fruit:time machine = yes")
        acls = db.query(AclEntry).filter(AclEntry.share_id == share.id).all()
        valid_users = [a.principal for a in acls if a.permission in ("rw", "ro")]
        if valid_users:
            lines.append("   valid users = " + " ".join(valid_users))
        lines.append("")
    return "\n".join(lines) + "\n"


def write_samba_config(db: Session) -> None:
    content = render_samba(db)
    path = settings.samba_config_path
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")


def render_nftables(ruleset: str | None) -> str:
    if ruleset:
        return ruleset
    return """#!/usr/sbin/nft -f
flush ruleset
table inet filter {
  chain input {
    type filter hook input priority 0;
    policy drop;
    iif "lo" accept
    ct state established,related accept
    tcp dport { 22, 80, 443, 445, 2049 } accept
    icmp type echo-request accept
  }
  chain forward {
    type filter hook forward priority 0;
    policy drop;
  }
  chain output {
    type filter hook output priority 0;
    policy accept;
  }
}
"""


def write_nftables_config(db: Session, custom: str | None = None) -> None:
    path = settings.nftables_config_path
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(render_nftables(custom), encoding="utf-8")
